    getTimeField: function(cfg) {
        if(!this._timeField)
            this._timeField = new Ext.form.TextField({
                'name': "number_hours",
                'fieldLabel': "Total Horas",
                'width': 60,
                'emptyText':'00:00',
                'readOnly':cfg.action == 'create'?false:!cfg.values.is_update,
                'enableKeyEvents': true,
                'hidden':true,
                'submitValue': true,
                'allowBlank': false,
                'validator': function(value) {
                    var tests = [
                        /^$/,
                        /^[0-2]$/,
                        /^([0-1][0-9]|2[0-3])$/,
                        /^([0-1][0-9]|2[0-3]):$/,
                        /^([0-1][0-9]|2[0-3]):[0-5]$/,
                        /^([0-1][0-9]|2[0-3]):[0-5][0-9]$/,
                    ];

                    var flag = true;
                    Ext.each(tests, function(t) {
                        if(t.test(value)) {
                            flag = true;
                            return false;
                        }
                    });

                    return (flag ? true : 'Horário informado é inválido.');
                },
                'listeners': {
                    'scope': this,
                    'keypress': function(field, evt) {
                        if(evt.charCode >= 48 && evt.charCode <= 57) {
                            var value = field.getValue();
                            if(value.length == 2)
                                field.setValue(value + ':')
                            else if(value.length == 5)
                                evt.stopEvent()
                        }
                        else if(evt.charCode != 0){
                            evt.stopEvent();
                            //console.debug([evt, evt.charCode, evt.keyCode]);
                        }
                    },
                    change: function(field, newValue, oldValue) {this}
                }
            });

        return this._timeField;
    },

