    getEndDisplay: function () {
        if (this.getStartDate().getValue() != '' && this.getDays().getValue() > 0) {
            data = Date.parseDate(this.getStartDate().value, 'd/m/Y');
            data.setDate(data.getDate() + (parseInt(this.getDays().getValue() - 1)));
            this.getEndDate().setValue(Ext.util.Format.date(data, 'd/m/Y'));
        }
    },

    setDatasFaltaDisplay: function (cfg) {
        if (cfg && cfg.params && cfg.params.total_dias) {
            this.getHourField(cfg).hide()
            this.getMinuteField(cfg).hide()
            this.getStartDate(cfg).show()
            this.getDays(cfg).show()
            this.getEndDate(cfg).show()

            this.getRadioHour(cfg).disable();
            this.getRadioDay(cfg).disable();
            this.getRadioDay(cfg).setValue(true);
            
            data_falta = Date.parseDate(cfg.params.data_inicio.value, 'd/m/Y');
            this.getStartDate(cfg).setValue(Ext.util.Format.date(data_falta, 'd/m/Y'));
            this.getStartDate(cfg).value = Ext.util.Format.date(data_falta, 'd/m/Y');
            this.getStartDate(cfg).readOnly = true;

            this.getDays(cfg).setValue(cfg.params.total_dias.getValue());
            this.getDays(cfg).value = cfg.params.total_dias.getValue();
            this.getDays(cfg).readOnly = true;
            
            data_falta.setDate(data_falta.getDate() + (parseInt(cfg.params.total_dias.getValue() - 1)));
            this.getEndDate(cfg).setValue(Ext.util.Format.date(data_falta, 'd/m/Y'));
            this.getEndDate(cfg).value = Ext.util.Format.date(data_falta, 'd/m/Y');
            this.getEndDate(cfg).readOnly = true;
        }
    },

