    validate_hour_limit:function(qtd_hour){
        if (qtd_hour > 8)
            return false
        return true
    },

    set_number_hour:function(number_hours){
        return parseFloat(number_hours.replace(':','.'))
    },

    pre_save:function(){
        this.getTimeField().setValue(this.getHourField().lastSelectionText+":"+this.getMinuteField().lastSelectionText)
        var number_hours = this.getTimeField().getValue()
        var radio_hour = this.getRadioHour()
        select_option = radio_hour.checked == true?1:0
        if (select_option == 1){
            if(number_hours && this.set_number_hour(number_hours) > 0 && this.validate_hour_limit(this.set_number_hour(number_hours))){
                this.getDays().setValue(1)
                this.getEndDisplay()
                this.save()
            }else{
                if (number_hours && !this.validate_hour_limit(this.set_number_hour(number_hours)))
                    Ext.Msg.show({
                        title: 'Error',
                        msg: "Quantidade máxima de horas permitidas (8).",
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    })
                else
                    Ext.Msg.show({
                        title: 'Error',
                        msg: "Preencha todos os campos corretamente.",
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    })
                this.getTimeField().setValue('')
            }

        }else if(select_option == 0){
            this.getTimeField().setValue('00:00')
            this.save()
        }
        
    }

   
